import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String s = next();

        int[] counts = new int[26];
        for (char c : s.toCharArray()) counts[c - 'a']++;
        PriorityQueue<int[]> heap = new PriorityQueue<>((p, q) -> p[0] != q[0] ? q[0] - p[0] : p[1] - q[1]);
        for (int i = 0; i < 26; i++) {
            if (counts[i] > 0) heap.add(new int[] {counts[i], i});
        }
        StringBuilder result = new StringBuilder();
        int prev = -1;
        boolean ok = true;
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            int[] held = null;
            if (top[1] == prev) {
                if (heap.isEmpty()) {
                    ok = false;
                    break;
                }
                held = top;
                top = heap.poll();
            }
            result.append((char) ('a' + top[1]));
            prev = top[1];
            if (top[0] > 1) heap.add(new int[] {top[0] - 1, top[1]});
            if (held != null) heap.add(held);
        }
        System.out.println(ok ? result.toString() : "impossible");
    }
}
